func driveFixture(t *testing.T,scope string)(*Manager,*fakeDriveBridge){t.Helper();cfg:=testConfig(t);cfg.Connectors=map[string]config.Connector{};m,e:=New(cfg);if e!=nil{t.Fatal(e)};_,app,c:=lexopenNewAliasFixture("google");app.Settings["oauth_scopes"]=scope;if scope==LexOpenDriveManageScope{app.Settings["oauth_lexopen_drive_management"]="v1"};c.Account="fixture-account";c.Expiry=time.Now().Add(time.Hour);if e=m.OAuth().ImportCredentials(driveTestAlias,app,c);e!=nil{t.Fatal(e)};fake:=&fakeDriveBridge{t:t,files:map[string]driveFile{},data:map[string][]byte{}};parent:=driveFile{ID:"folder_exact",Name:"cause",MIME:"application/vnd.google-apps.folder",Version:"8"};parent.Capabilities.CanAddChildren=true;fake.files["folder_exact"]=parent;fake.files["root"]=parent;old:=driveFile{ID:"old_exact",Name:"original.pdf",MIME:"application/pdf",Parents:[]string{"folder_exact"},Version:"12",Size:"3"};old.Capabilities.CanEdit=true;fake.files[old.ID]=old;prior:=lexopenDriveHTTPDo;lexopenDriveHTTPDo=fake.do;t.Cleanup(func(){lexopenDriveHTTPDo=prior});return m,fake}
func(f *fakeDriveBridge)response(status int,value any)(*http.Response,error){raw,_:=json.Marshal(value);return &http.Response{StatusCode:status,Header:http.Header{"Content-Type":[]string{"application/json"}},Body:io.NopCloser(bytes.NewReader(raw))},nil}
func(f *fakeDriveBridge)do(r *http.Request)(*http.Response,error){f.calls++;if r.URL.Scheme!="https"||r.URL.Host!="www.googleapis.com"||r.Header.Get("Authorization")==""{f.t.Fatal("unexpected destination/auth")};if r.Method=="GET"{if f.denyRead{return f.response(403,map[string]any{"error":"private-reflected-data"})};if r.URL.Path=="/drive/v3/files/generateIds"{f.generated++;return f.response(200,map[string]any{"ids":[]string{"new_exact_"+strconv.Itoa(f.generated)}})};id:=strings.TrimPrefix(r.URL.Path,"/drive/v3/files/");file,ok:=f.files[id];if !ok{return f.response(404,map[string]any{"error":"private-reflected-data"})};if r.URL.Query().Get("alt")=="media"{return &http.Response{StatusCode:200,Header:http.Header{"Content-Type":[]string{file.MIME}},Body:io.NopCloser(bytes.NewReader(f.data[id]))},nil};if f.corruptHash&&strings.HasPrefix(id,"new_exact_"){file.SHA256=strings.Repeat("0",64)};return f.response(200,file)};if r.Method!="POST"||(r.URL.Path!="/drive/v3/files"&&r.URL.Path!="/upload/drive/v3/files"){f.t.Fatal("unexpected write method/path")};if f.beforeWrite!=nil{f.beforeWrite()};f.writes++;var meta struct{ID string `json:"id"`;Name string `json:"name"`;MIME string `json:"mimeType"`;Parents []string `json:"parents"`;AppProperties map[string]string `json:"appProperties"`};var content []byte;if r.URL.Path=="/upload/drive/v3/files"{mt,params,e:=mime.ParseMediaType(r.Header.Get("Content-Type"));if e!=nil||mt!="multipart/related"{f.t.Fatal("invalid multipart type")};reader:=multipart.NewReader(r.Body,params["boundary"]);first,e:=reader.NextPart();if e!=nil||json.NewDecoder(first).Decode(&meta)!=nil{f.t.Fatal("invalid multipart metadata")};second,e:=reader.NextPart();if e!=nil{f.t.Fatal(e)};content,_=io.ReadAll(second);if _,e=reader.NextPart();e!=io.EOF{f.t.Fatal("extra upload parts")}}else if json.NewDecoder(r.Body).Decode(&meta)!=nil{f.t.Fatal("invalid folder request")};if _,exists:=f.files[meta.ID];exists{f.t.Fatal("duplicate mutation id")};if !lexopenDriveID.MatchString(meta.ID)||len(meta.Parents)!=1||meta.Parents[0]!="folder_exact"||!lexopenDriveHex.MatchString(meta.AppProperties["lexopenRequest"]){f.t.Fatal("unbound mutation")};file:=driveFile{ID:meta.ID,Name:meta.Name,MIME:meta.MIME,Parents:meta.Parents,Version:"1",Size:strconv.Itoa(len(content)),AppProperties:meta.AppProperties};if meta.MIME!="application/vnd.google-apps.folder"{sum:=sha256.Sum256(content);file.SHA256=hex.EncodeToString(sum[:])};f.files[file.ID]=file;f.data[file.ID]=content;if f.loseACK{return nil,errors.New("private-reflected-network-detail")};return f.response(200,map[string]any{"id":file.ID})}
func driveTestCommand(t *testing.T,m *Manager,action string)DriveCommand{t.Helper();status,e:=m.LexOpenDriveStatus(driveTestAlias);if e!=nil{t.Fatal(e)};data:=[]byte("%PDF-fixture-exact");sum:=sha256.Sum256(data);c:=DriveCommand{RequestID:"drive-request-one",ContextKey:strings.Repeat("a",64),BindingRevision:status.AccountRevision,Action:action,FolderID:"folder_exact",Name:"revision.pdf",MIME:"application/pdf",ContentBase64:base64.StdEncoding.EncodeToString(data),SHA256:hex.EncodeToString(sum[:]),Confirmed:true};if action=="create_folder"{c.Name="Documents";c.MIME="";c.ContentBase64="";c.SHA256=""};if action=="save_version"{c.FileID="old_exact";c.ExpectedVersion="12"};return c}
func TestLexOpenDriveManagementStatusROFullRevisionStableAcrossRefresh(t *testing.T){for _,scope:=range []string{lexopenDriveMetadataScope,lexopenDriveReadScope,LexOpenDriveManageScope}{t.Run(scope,func(t *testing.T){m,f:=driveFixture(t,scope);a,e:=m.LexOpenDriveStatus(driveTestAlias);if e!=nil||a.CanManageFiles!=(scope==LexOpenDriveManageScope)||a.CanReadFiles!=(scope!=lexopenDriveMetadataScope)||!lexopenDriveHex.MatchString(a.AccountRevision)||f.calls!=0{t.Fatal("wrong local account capability")};c,_:=m.OAuthCredentials(driveTestAlias);c.AccessToken="rotated-access";c.RefreshToken="rotated-refresh";c.Expiry=time.Now().Add(2*time.Hour);if e=m.SaveOAuthCredentials(driveTestAlias,c);e!=nil{t.Fatal(e)};b,_:=m.LexOpenDriveStatus(driveTestAlias);if b.AccountSubjectHash!=a.AccountSubjectHash||!lexopenDriveHex.MatchString(a.AccountSubjectHash){t.Fatal("account subject proof missing or changed during refresh")};if b.AccountRevision!=a.AccountRevision{t.Fatal("refresh changed binding")};app,_:=m.OAuthApp(driveTestAlias);if e=m.OAuth().ImportCredentials(driveTestAlias,app,c);e!=nil{t.Fatal(e)};b,_=m.LexOpenDriveStatus(driveTestAlias);if b.AccountRevision==a.AccountRevision{t.Fatal("new consent failed to change binding")};raw,_:=json.Marshal(a);for _,s:=range []string{"fixture-create-client","fixture-create-secret","fixture-account","rotated-refresh"}{if strings.Contains(string(raw),s){t.Fatal("status leaked account credentials")}}})}}
func TestLexOpenDriveManagementWritesPreserveOriginalAndOneUse(t *testing.T){for _,action:=range []string{"create_folder","upload_file","save_version"}{t.Run(action,func(t *testing.T){m,f:=driveFixture(t,LexOpenDriveManageScope);c:=driveTestCommand(t,m,action);before:=f.files["old_exact"];result,e:=m.LexOpenDriveCommand(context.Background(),driveTestAlias,c);if e!=nil||result.State!="drive_verified"||result.Receipt==nil{t.Fatal("reviewed command failed",e)};r:=result.Receipt;if r.FileID==c.FileID||r.ParentID!="folder_exact"||r.ContextKey!=c.ContextKey||r.AccountRevision!=c.BindingRevision||r.Action!=action||r.SHA256!=c.SHA256||r.FolderID!=c.FolderID||f.writes!=1{t.Fatal("wrong exact verified receipt")};if action=="save_version"&&(r.PreviousFileID!="old_exact"||r.PreviousVersion!="12"){t.Fatal("save version did not preserve source identity")};if f.files["old_exact"].Version!=before.Version||f.files["old_exact"].Name!=before.Name{t.Fatal("original file mutated")};calls:=f.calls;again,e:=m.LexOpenDriveCommand(context.Background(),driveTestAlias,c);if e!=nil||again.Receipt.FileID!=r.FileID||f.calls!=calls{t.Fatal("same request replayed")};changed:=c;changed.Name="different.pdf";if _,e=m.LexOpenDriveCommand(context.Background(),driveTestAlias,changed);e==nil||f.calls!=calls{t.Fatal("same id changed arguments")};beforeGeneric:=f.calls;generic:=m.Connectors().Call(context.Background(),connector.Call{Name:driveTestAlias,Args:map[string]any{"action":"upload","name":"generic.txt","content":"not-authorized"}},[]string{driveTestAlias});if generic.Err==""||f.calls!=beforeGeneric{t.Fatal("managed Google generic API bypassed write bridge")};if e=connector.LexOpenValidateEasyFileCall("google-workspace",map[string]any{"action":"upload","name":"x","content":"x"});e==nil{t.Fatal("generic model write became available")};ledger,_:=os.ReadFile(m.driveLedgerPath());if strings.Contains(string(ledger),c.ContentBase64)&&c.ContentBase64!=""{t.Fatal("ledger stored document body")};st,_:=os.Stat(m.driveLedgerPath());if st.Mode().Perm()!=0600{t.Fatal("ledger not private")}})}}
func TestLexOpenDriveManagementLostACKRestartReconcileOnlyReads(t *testing.T){m,f:=driveFixture(t,LexOpenDriveManageScope);c:=driveTestCommand(t,m,"upload_file");f.loseACK=true;if _,e:=m.LexOpenDriveCommand(context.Background(),driveTestAlias,c);e==nil{t.Fatal("lost ACK reported success")};calls:=f.calls;if _,e:=m.LexOpenDriveCommand(context.Background(),driveTestAlias,c);e==nil||f.calls!=calls{t.Fatal("unknown replay reached provider")};other:=c;other.RequestID="another-id";if _,e:=m.LexOpenDriveCommand(context.Background(),driveTestAlias,other);e==nil||f.calls!=calls{t.Fatal("unknown bypassed with a new request id")};s,e:=m.LexOpenDriveCommandStatus(driveTestAlias,c.RequestID);if e!=nil||s.State!="unknown"||f.calls!=calls{t.Fatal("ledger lookup reached provider")};cfg:=m.cfg;again,e:=New(cfg);if e!=nil{t.Fatal(e)};f.loseACK=false;result,e:=again.LexOpenDriveReconcile(context.Background(),driveTestAlias,c.RequestID,DriveReconcile{c.ContextKey,c.BindingRevision,true});if e!=nil||result.State!="drive_verified"||f.writes!=1{t.Fatal("read-only reconciliation failed or rewrote")};calls=f.calls;if _,e=again.LexOpenDriveReconcile(context.Background(),driveTestAlias,c.RequestID,DriveReconcile{c.ContextKey,c.BindingRevision,true});e!=nil||f.calls!=calls{t.Fatal("verified reconciliation unnecessarily called provider")}}
func TestLexOpenDriveManagementUnknownMismatchNeverClearsOrWrites(t *testing.T){m,f:=driveFixture(t,LexOpenDriveManageScope);c:=driveTestCommand(t,m,"upload_file");f.loseACK=true;m.LexOpenDriveCommand(context.Background(),driveTestAlias,c);f.loseACK=false;f.corruptHash=true;if _,e:=m.LexOpenDriveReconcile(context.Background(),driveTestAlias,c.RequestID,DriveReconcile{c.ContextKey,c.BindingRevision,true});e==nil||f.writes!=1{t.Fatal("mismatched remote content reconciled")};f.denyRead=true;if _,e:=m.LexOpenDriveReconcile(context.Background(),driveTestAlias,c.RequestID,DriveReconcile{c.ContextKey,c.BindingRevision,true});e==nil||f.writes!=1{t.Fatal("403 discarded uncertainty")};state,_:=m.LexOpenDriveCommandStatus(driveTestAlias,c.RequestID);if state.State!="unknown"{t.Fatal("unknown was cleared")}}
func TestLexOpenDriveManagementLedgerSavedBeforeMutationAndConcurrentOnce(t *testing.T){m,f:=driveFixture(t,LexOpenDriveManageScope);c:=driveTestCommand(t,m,"upload_file");f.beforeWrite=func(){l,e:=m.driveLedger();if e!=nil||l.Records[c.RequestID]==nil||l.Records[c.RequestID].State!="executing"||l.Records[c.RequestID].NewFileID==""{t.Fatal("mutation happened before durable execution reservation")}};var wg sync.WaitGroup;for range 8{wg.Add(1);go func(){defer wg.Done();if _,e:=m.LexOpenDriveCommand(context.Background(),driveTestAlias,c);e!=nil{var d *DriveError;if !errors.As(e,&d)||d.Code!="drive_outcome_unknown"{t.Error("concurrent exact command failed")}}}()};wg.Wait();if f.writes!=1{t.Fatal("concurrent command executed twice")}}
func TestLexOpenDriveManagementValidationAndStalePlanZeroProvider(t *testing.T){for _,alter:=range []func(*DriveCommand){func(c *DriveCommand){c.Confirmed=false},func(c *DriveCommand){c.BindingRevision=strings.Repeat("0",64)},func(c *DriveCommand){c.SHA256=strings.Repeat("0",64)},func(c *DriveCommand){c.Action="update_file"},func(c *DriveCommand){c.MIME="application/vnd.google-apps.document"},func(c *DriveCommand){c.FolderID="https://evil.invalid"},func(c *DriveCommand){c.Name="../escape"},func(c *DriveCommand){c.ContextKey="other-cause"}}{m,f:=driveFixture(t,LexOpenDriveManageScope);c:=driveTestCommand(t,m,"upload_file");alter(&c);if _,e:=m.LexOpenDriveCommand(context.Background(),driveTestAlias,c);e==nil||f.calls!=0{t.Fatal("invalid or stale plan reached provider")}};m,f:=driveFixture(t,lexopenDriveReadScope);c:=driveTestCommand(t,m,"upload_file");if _,e:=m.LexOpenDriveCommand(context.Background(),driveTestAlias,c);e==nil||f.calls!=0{t.Fatal("readonly grant could write")}}
func TestLexOpenDriveManagementReadAllowlistMaxAndNoRedirect(t *testing.T){m,f:=driveFixture(t,lexopenDriveReadScope);status,_:=m.LexOpenDriveStatus(driveTestAlias);valid:=DriveRead{BindingRevision:status.AccountRevision,Path:"/drive/v3/files/folder_exact",Query:map[string]string{"fields":"id,name,mimeType,parents,trashed"},MaxBytes:4096};r,e:=m.LexOpenDriveRead(context.Background(),driveTestAlias,valid);if e!=nil||r.Status!=200||r.Bytes==0||r.SHA256==""{t.Fatal("read bridge failed")};before:=f.calls;for _,bad:=range []DriveRead{{BindingRevision:status.AccountRevision,Path:"https://evil.invalid",MaxBytes:10},{BindingRevision:status.AccountRevision,Path:"/gmail/v1/users/me/messages",MaxBytes:10},{BindingRevision:status.AccountRevision,Path:"/drive/v3/files/folder_exact",Query:map[string]string{"fields":"webContentLink"},MaxBytes:10},{BindingRevision:status.AccountRevision,Path:"/drive/v3/files/generateIds",MaxBytes:10},{BindingRevision:status.AccountRevision,Path:valid.Path,MaxBytes:lexopenDriveMaxRead+1},{BindingRevision:strings.Repeat("0",64),Path:valid.Path,MaxBytes:10}}{if _,e=m.LexOpenDriveRead(context.Background(),driveTestAlias,bad);e==nil||f.calls!=before{t.Fatal("invalid read reached provider")}};valid.MaxBytes=1;if _,e=m.LexOpenDriveRead(context.Background(),driveTestAlias,valid);e==nil{t.Fatal("response exceeded caller limit")}}
func TestLexOpenDriveManagementLedgerFailurePreventsMutation(t *testing.T){m,f:=driveFixture(t,LexOpenDriveManageScope);if e:=os.Mkdir(m.driveLedgerPath(),0700);e!=nil{t.Fatal(e)};if _,e:=m.LexOpenDriveCommand(context.Background(),driveTestAlias,driveTestCommand(t,m,"upload_file"));e==nil||f.calls!=0{t.Fatal("bad ledger executed command")};if _,e:=m.LexOpenDriveCommandStatus(driveTestAlias,"id");e==nil{t.Fatal("unreadable ledger presented not-found")};_ = filepath.Separator}

