type driveAuthTransport func(*http.Request)(*http.Response,error)
func(f driveAuthTransport)RoundTrip(r *http.Request)(*http.Response,error){return f(r)}
func TestLexOpenDriveManagementIdentityMutationsWaitForWriteWithoutCredentialDeadlock(t *testing.T){for _,mutation:=range []string{"import","set","remove","learn"}{t.Run(mutation,func(t *testing.T){m,f:=driveFixture(t,LexOpenDriveManageScope);c:=driveTestCommand(t,m,"upload_file");started,release:=make(chan struct{}),make(chan struct{});f.beforeWrite=func(){close(started);<-release};written:=make(chan error,1);go func(){_,e:=m.LexOpenDriveCommand(context.Background(),driveTestAlias,c);written<-e}();<-started;app,_:=m.OAuthApp(driveTestAlias);cred,_:=m.OAuthCredentials(driveTestAlias);changed:=make(chan error,1);go func(){switch mutation{case "import":changed<-m.OAuth().ImportCredentials(driveTestAlias,app,cred);case "set":changed<-m.SetConnector(driveTestAlias,m.cfg.Connectors[driveTestAlias],ConnectorChange{});case "remove":changed<-m.RemoveConnector(driveTestAlias);case "learn":changed<-m.SaveOAuthSettings(driveTestAlias,map[string]string{"client_id":"another-client"})}}();select{case <-changed:t.Fatal("identity mutation acknowledged while an old-token write was still in flight");case <-time.After(15*time.Millisecond):};close(release);select{case e:=<-written:if e!=nil{t.Fatal(e)};case <-time.After(2*time.Second):t.Fatal("credential/Drive mutex deadlock")};select{case e:=<-changed:if e!=nil{t.Fatal(e)};case <-time.After(2*time.Second):t.Fatal("identity mutation stayed blocked")};if f.writes!=1{t.Fatal("mutation altered provider write count")}})}}
func TestLexOpenDriveManagementRefreshUnlockPreservesOtherAccountLedger(t *testing.T){m,f:=driveFixture(t,LexOpenDriveManageScope);_,app,creds:=lexopenNewAliasFixture("google");app.Settings["oauth_scopes"]=LexOpenDriveManageScope;app.Settings["oauth_lexopen_drive_management"]="v1";creds.Account="second-account";creds.Expiry=time.Now().Add(time.Hour);otherAlias:="altazor-google-abcdef0123456789";if e:=m.OAuth().ImportCredentials(otherAlias,app,creds);e!=nil{t.Fatal(e)};first:=driveTestCommand(t,m,"upload_file");second:=first;second.RequestID="second-account-command";status,_:=m.LexOpenDriveStatus(otherAlias);second.BindingRevision=status.AccountRevision;expired,_:=m.OAuthCredentials(driveTestAlias);expired.Expiry=time.Now().Add(-time.Minute);if e:=m.SaveOAuthCredentials(driveTestAlias,expired);e!=nil{t.Fatal(e)};started,release:=make(chan struct{}),make(chan struct{});previous:=http.DefaultTransport;http.DefaultTransport=driveAuthTransport(func(r *http.Request)(*http.Response,error){if r.URL.String()!="https://oauth2.googleapis.com/token"{t.Fatal("unexpected auth endpoint")};close(started);<-release;return &http.Response{StatusCode:200,Body:io.NopCloser(strings.NewReader(`{"access_token":"fixture-refreshed","refresh_token":"fixture-rotated","expires_in":3600,"scope":"https://www.googleapis.com/auth/drive"}`))},nil});defer func(){http.DefaultTransport=previous}();done1,done2:=make(chan error,1),make(chan error,1);go func(){_,e:=m.LexOpenDriveCommand(context.Background(),driveTestAlias,first);done1<-e}();<-started;state,e:=m.LexOpenDriveCommandStatus(driveTestAlias,first.RequestID);if e!=nil||state.State!="unknown"{t.Fatal("active preparation reported definitive failure")};go func(){_,e:=m.LexOpenDriveCommand(context.Background(),otherAlias,second);done2<-e}();deadline:=time.After(2*time.Second);for{ledger,e:=m.driveLedger();if e==nil&&len(ledger.Records)==2{break};select{case <-deadline:t.Fatal("second account could not reserve while token refresh waited");default:time.Sleep(time.Millisecond)}};close(release);for _,ch:=range []chan error{done1,done2}{select{case e:=<-ch:if e!=nil{t.Fatal(e)};case <-time.After(2*time.Second):t.Fatal("refresh or ledger deadlocked")}};ledger,e:=m.driveLedger();if e!=nil||len(ledger.Records)!=2||ledger.Records[first.RequestID].State!="drive_verified"||ledger.Records[second.RequestID].State!="drive_verified"||f.writes!=2{t.Fatal("token unlock overwrote another account's durable record")}}
